/* Original study answers derived from user-created annotated answer booklet. Educational use; clinical audit ongoing. */
window.VPQ_CARLSON_186=[{"id":"carlson186-001","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":1,"prompt":"Why can many small-molecule drugs enter the glomerular filtrate, and what limits filtration?","answer":"Most conventional drugs are small enough to cross the glomerular filtration barrier. Dr. Carlson uses approximately 68 kDa as the size threshold; clinically only the unbound fraction is readily filtered, and tubular secretion/reabsorption also matter.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Why do most drug get dumped into the glomerular filtrate? They are smaller than 68kd","promptEditedForRecall":true},{"id":"carlson186-002","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":2,"prompt":"Which species is commonly treated using specially formulated transdermal medications, and why?","answer":"Cats: transdermal formulations can avoid difficult oral administration, although absorption and efficacy are highly formulation-dependent.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Which species is most likely to receive a drug transdermally? Cats","promptEditedForRecall":true},{"id":"carlson186-003","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":3,"prompt":"What is the volume of distribution and why is it important?","answer":"Apparent volume of distribution (Vd) relates the amount of drug in the body to its measured plasma concentration: Vd = amount / plasma concentration. Low Vd suggests plasma confinement; high Vd suggests extensive tissue uptake, influencing loading doses and half-life.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-004","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":4,"prompt":"What two major molecular target categories are emphasized in introductory pharmacology?","answer":"Receptors and enzymes. Receptors transduce chemical signals; enzymes catalyze reactions. Other important targets include channels, transporters, DNA, ribosomes, and cell-wall machinery.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What are the two most important drug targets? Receptors and enzymes","promptEditedForRecall":true},{"id":"carlson186-005","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":5,"prompt":"Contrast pharmacodynamics and pharmacokinetics","answer":"Pharmacodynamics (PD) = what drug binding does to the organism (mechanism, potency, efficacy, toxicity); pharmacokinetics (PK) = what happens to the drug (absorption, distribution, metabolism, excretion). Both determine whether adequate target exposure causes the desired response.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-006","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":6,"prompt":"What is an agonist?","answer":"An agonist binds a receptor and increases its signaling. A full agonist can generate a maximal system response; a partial agonist has lower intrinsic efficacy even with high receptor occupancy.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-007","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":7,"prompt":"What is an allosteric modulator?","answer":"An allosteric modulator binds a site different from the main agonist (orthosteric) site and changes receptor response. Positive allosteric modulators enhance, negative ones diminish signaling; some require the endogenous agonist to be present.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-008","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":8,"prompt":"What is an antagonist and what are the three main types?","answer":"An antagonist opposes agonist-mediated effects. Carlson contrasts neutral antagonists (block agonist without changing constitutive signaling), inverse agonists (reduce constitutive baseline signaling), and desensitizing agonists (first activate, then reduce response through receptor adaptation). The last is initially an agonist, not a conventional neutral blocker.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-009","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":9,"prompt":"What are EC50 and ED50 values?","answer":"EC50 is the concentration eliciting half-maximal effect in a concentration-response experiment; ED50 is a dose producing a defined effect in 50% of subjects, or a half-maximal response under a specified dose framework. Lower EC50/ED50 indicates greater potency under comparable conditions, not necessarily greater efficacy.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-010","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":10,"prompt":"What is efficacy and what is efficacious?","answer":"Efficacy is the maximal response a drug can produce (Emax); efficacious describes a treatment that actually delivers a useful clinical outcome. Potency is distinct: a less-potent drug can still have greater maximal efficacy.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-011","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":11,"prompt":"Define competitive, non-competitive, reversible, and irreversible antagonists/inhibitors","answer":"Competitive antagonists compete with agonist for the same site and, when reversible, often shift the dose-response curve right without lowering Emax. Noncompetitive inhibitors block signaling at another site or through insurmountable interaction, often reducing Emax; reversible binding can dissociate, whereas irreversible inhibition persists until new functional target is produced.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-012","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":12,"prompt":"What are affinity and KD?","answer":"Affinity is a drug's tendency to bind a target. Dissociation constant Kd = [free drug][free receptor]/[drug-receptor complex]; a smaller Kd corresponds to stronger binding. Affinity alone does not determine efficacy.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-013","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":13,"prompt":"What are selectivity and specificity?","answer":"Selectivity is a preference for one target/subtype over another, often inferred by comparing Kd or functional concentrations; specificity is the ideal of interacting with only one target. Drugs rarely have absolute specificity, and off-target effects increase as exposure rises.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-014","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":14,"prompt":"What do the therapeutic index and standard safety margin tell us about a drug?","answer":"Therapeutic index (e.g., TD50/ED50 or LD50/ED50 in experimental contexts) and standard safety margin assess separation of effective and toxic exposures. The margin uses defined low-toxicity/high-efficacy endpoints; both describe population-level safety, not a guarantee for an individual animal.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What are the therapeutic index and standard safety margin indicative of? Drug safety","promptEditedForRecall":true},{"id":"carlson186-015","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":15,"prompt":"What is the predominant mechanism by which many drugs cross the gastrointestinal epithelium?","answer":"Most orally absorbable small molecules cross the intestinal epithelial lipid membrane by passive diffusion down a concentration gradient. Ionization, lipid solubility, drug size, transporters and formulation determine exceptions.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"How do most drugs cross the GI barrier? Passive (simple) diffusion","promptEditedForRecall":true},{"id":"carlson186-016","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":16,"prompt":"What is the pK value and why does it matter for drug absorption and distribution?","answer":"pKa (sometimes called the pK value here) is the pH at which a weak acid/base is 50% ionized; ionization affects lipid diffusion and ion trapping. Weak acids are increasingly ionized at high pH; weak bases at low pH.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-017","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":17,"prompt":"What are AUC, Cmax, and Tmax?","answer":"AUC = area under plasma concentration-time curve (overall exposure); Cmax = maximum measured plasma concentration; Tmax = time of that peak. Together these inform extent/rate of exposure and antibiotic PK/PD targets.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-018","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":18,"prompt":"What is bioavailability?","answer":"Bioavailability (F) is the fraction of administered dose reaching systemic circulation unchanged; IV = 100% by definition, whereas oral F is affected by dissolution, uptake and first-pass loss.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-019","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":19,"prompt":"What is the 1st-pass effect?","answer":"First-pass effect is presystemic metabolism and/or extraction by intestinal tissue and liver after oral absorption via portal blood, reducing unchanged systemic availability.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-020","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":20,"prompt":"What are the two factors influencing drug distribution?","answer":"**1. Plasma drug concentration (especially free/unbound concentration):** The unbound drug concentration in plasma helps determine the concentration gradient that drives movement into tissues. Plasma protein binding changes how much free drug is available. **2. Physicochemical/electrochemical properties:** Lipophilicity, molecular size, polarity/charge and degree of ionization determine how readily drug crosses capillary and cell membranes. **Additional clinical modifiers:** Tissue blood flow/perfusion, pH, tissue binding, inflammation and physiological barriers affect distribution rate and extent. These expand the two-part lecture framing, not replace it.","reviewStatus":"Answer checked against pharmacokinetics references; lecture-specific two-factor terminology reported by student, original slide confirmation pending","originalAnswer":"Main distribution determinants stressed in class are lipid solubility/charge (ability to enter tissues) and protein binding (free fraction). Perfusion, tissue barriers and inflammation also modify effective distribution."},{"id":"carlson186-021","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":21,"prompt":"What is a major biological purpose of drug metabolism, particularly for lipophilic compounds?","answer":"Metabolism typically makes lipophilic drugs more polar/water soluble so they can be excreted, often through kidneys. It may also activate prodrugs or generate toxic metabolites, so it is not always simple detoxification.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What is the biologic “purpose” of drug metabolism? To polarize a drug for renal elimination","promptEditedForRecall":true},{"id":"carlson186-022","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":22,"prompt":"Why is clearance important?","answer":"Clearance (CL) is the volume of plasma effectively cleared of drug per time and governs maintenance dose and total exposure. Renal/hepatic disease or interacting drugs can lower CL and raise toxicity risk.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-023","lecture":"Lecture 1","section":"Introduction to Pharmacology","number":23,"prompt":"Why is elimination half-life important?","answer":"Elimination half-life is the time for plasma concentration to decline by 50% during first-order elimination. It informs dose interval, accumulation, time to steady state and washout; half-life is linked to clearance and distribution (t½ ≈ 0.693 × Vd/CL in a simple model).","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-024","lecture":"Lecture 2","section":"Choosing an Appropriate Antibiotic","number":1,"prompt":"What is the first question you should ask yourself when selecting an antibiotic?","answer":"First determine whether a bacterial infection actually exists and warrants an antibiotic. Uncomplicated viral or noninfectious inflammatory disease does not respond to antibacterial therapy; sample and perform source control when appropriate.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-025","lecture":"Lecture 2","section":"Choosing an Appropriate Antibiotic","number":2,"prompt":"What are the two main parameters that dictate the spectrum (i.e., the range of bacteria harmed by a given antibiotic) of an antibiotic?","answer":"Spectrum depends chiefly on whether the microorganism possesses a susceptible molecular target and whether the drug can enter/reach that target (cell envelope, oxygen dependence and intrinsic defenses). Gram status and anaerobic/aerobic biology therefore matter.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-026","lecture":"Lecture 2","section":"Choosing an Appropriate Antibiotic","number":3,"prompt":"How are antimicrobial spectrum and pharmacodynamics related, and how do they differ?","answer":"Spectrum says which organisms can be affected; PD describes what exposure does to those organisms. MIC, permeability, concentration-dependent killing and post-antibiotic effects overlap both ideas; susceptible in vitro does not guarantee site exposure.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Please keep in mind that Spectrum and Pharmacodynamics have some overlap.","promptEditedForRecall":true},{"id":"carlson186-027","lecture":"Lecture 2","section":"Choosing an Appropriate Antibiotic","number":4,"prompt":"Why aren't bactericidal antibiotics always superior to bacteriostatic antibiotics in clinical practice?","answer":"Bactericidal killing is advantageous in some serious infections, but bacteriostatic agents are highly effective when host immunity clears suppressed organisms. Cidal/static designation depends on drug-organism-exposure conditions, so avoid using it as the sole selection rule.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Please keep in mind that bactericidal antibiotic would seem to be superior in all cases, bacteriostatic antibiotics are very important as you will see throughout this section.","promptEditedForRecall":true},{"id":"carlson186-028","lecture":"Lecture 2","section":"Choosing an Appropriate Antibiotic","number":5,"prompt":"Why do fluoroquinolones remain clinically important despite their serious potential adverse effects?","answer":"Fluoroquinolones may injure immature articular cartilage in young animals and some agents cause feline retinal toxicity; CNS effects can also occur. Despite these risks, their broad aerobic coverage and favorable tissue PK make them important when properly indicated and stewarded.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Please note that while fluoroquinolones are implicated in serious adverse events in two separate physiologic systems, they are one of the most important classes of antibiotics.","promptEditedForRecall":true},{"id":"carlson186-029","lecture":"Lecture 2","section":"Choosing an Appropriate Antibiotic","number":6,"prompt":"What are the two facets of Compliance?","answer":"Compliance includes (1) whether the owner/handler can administer the route, timing and full course correctly and (2) whether the patient will accept/tolerate the preparation. Cost and frequency can affect both.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-030","lecture":"Lecture 2","section":"Choosing an Appropriate Antibiotic","number":7,"prompt":"What are the privileged sites that are important for Environment?","answer":"Protected/privileged infection locations include CNS/CSF, prostate, eye and intracellular compartments; bacteria may also hide in abscesses or biofilm. For SPACED, 'Environment' additionally includes food-safety residues, withdrawal and stewardship; do not confuse the two headings.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-031","lecture":"Lecture 2","section":"Choosing an Appropriate Antibiotic","number":8,"prompt":"What is the difference between an MIC and a breakpoint?","answer":"MIC is the lowest measured concentration that stops visible bacterial growth under standardized testing. A breakpoint is an interpretive threshold for susceptible/intermediate/resistant using drug, organism, site and achievable exposure; for example MIC exceeding a resistant breakpoint predicts likely failure at safe exposures.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-032","lecture":"Lecture 2","section":"Antibiotic Resistance","number":1,"prompt":"What is laboratory determined resistance and be prepared to identify it if given an example?","answer":"Laboratory resistance means the isolate's MIC lies in the resistant category relative to the specified clinical breakpoint. Example: an MIC of 64 µg/mL versus a susceptible cutoff of 8 µg/mL indicates resistance in that test context; compare the correct species/organism-specific breakpoint, not arbitrary concentrations.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-033","lecture":"Lecture 2","section":"Antibiotic Resistance","number":2,"prompt":"What are the active and passive mechanisms of resistance?","answer":"Active/acquired mechanisms include drug-inactivating enzymes (beta-lactamases), efflux pumps, altered targets, and alternative metabolic pathways. Intrinsic/passive mechanisms include inaccessible or absent targets, reduced envelope entry, oxygen-dependent uptake failure in anaerobes and poor access to dormant cells.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-034","lecture":"Lecture 2","section":"Antibiotic Resistance","number":3,"prompt":"Provide three guidelines for the prevention of antibiotic resistance.","answer":"Three good rules: prescribe only when bacterial disease merits therapy; take appropriate samples and use the narrowest effective, correctly dosed agent; ensure adequate site exposure, duration, adherence and reassessment/source control. Also prevent cross-contamination and respect food-animal restrictions.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-035","lecture":"Lecture 2","section":"Antibiotic Resistance","number":4,"prompt":"What is persistence?","answer":"Persisters are phenotypically tolerant subpopulations that survive drug treatment without stable inherited resistance or a necessarily increased MIC, then regrow after treatment. Dormancy, biofilm and protected niches contribute; distinguish recurrence from proven resistance.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-036","lecture":"Lecture 3","section":"Penicillins / Penems","number":1,"prompt":"What is the mechanism of action for penicillins?","answer":"Penicillins are beta-lactams that bind penicillin-binding proteins (PBPs/transpeptidases) and interrupt cross-linking of bacterial peptidoglycan. Mammalian cells lack this wall target.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-037","lecture":"Lecture 3","section":"Penicillins / Penems","number":2,"prompt":"Why are these drugs bactericidal?","answer":"The wall loses mechanical stability while the bacterium is growing, so water/osmotic stress can cause lysis and death: generally bactericidal. Activity often depends on active cell-wall synthesis.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-038","lecture":"Lecture 3","section":"Penicillins / Penems","number":3,"prompt":"What is the major resistance mechanism?","answer":"Beta-lactamase enzymes hydrolyze the beta-lactam ring; altered PBPs and restricted Gram-negative entry also confer resistance. Potentiators address only some enzymes.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-039","lecture":"Lecture 3","section":"Penicillins / Penems","number":4,"prompt":"What is the major side effect for penicillins?","answer":"Hypersensitivity/allergic reactions are emphasized; GI disturbances can also occur. Severity ranges from rash to anaphylaxis, and penicillin/cephalosporin cross-reactivity is not universally present or absent.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-040","lecture":"Lecture 3","section":"Penicillins / Penems","number":5,"prompt":"Describe the pharmacokinetics of penicillins in relationship to the MIC of the targeted bacteria and the kinetics of the bactericidal activity.","answer":"Beta-lactams are primarily TIME dependent: maximize the fraction of each interval free drug remains above MIC (fT>MIC), often with frequent doses or prolonged exposure. Killing is relatively slow, so a very high short-lived peak is less useful than adequate time above MIC.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-041","lecture":"Lecture 3","section":"Penicillins / Penems","number":6,"prompt":"Describe the paradox regarding the volume of distribution for penicillins.","answer":"Penicillins are generally ionized/polar in plasma, suggesting limited distribution into lipid-rich sites (low Vd), yet inflammation can disrupt capillaries/barriers and raise tissue penetration (the paradox). Individual drug chemistry and protein binding also matter.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-042","lecture":"Lecture 3","section":"Penicillins / Penems","number":7,"prompt":"Describe how sustained-release penicillins address the pharmacokinetic requirements of penicillins in regards to the MIC.","answer":"Depot formulations release active antibiotic gradually from the injection site to keep serum concentrations above MIC longer, reducing injection frequency; release must still achieve sufficient target exposure.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-043","lecture":"Lecture 3","section":"Penicillins / Penems","number":8,"prompt":"Describe the issues associated with sustained-release penicillins.","answer":"Procaine penicillin has a risk of serious neurologic excitation if procaine enters a horse's bloodstream inadvertently; local reactions, injection technique, variable depot release and food-animal rules also matter.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-044","lecture":"Lecture 3","section":"Penicillins / Penems","number":9,"prompt":"Name the penicillin potentiators and describe how they work.","answer":"Clavulanate, sulbactam and tazobactam inhibit susceptible beta-lactamases and protect the partner beta-lactam. They do not reverse altered PBPs, missing uptake or all enzyme classes.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-045","lecture":"Lecture 3","section":"Penicillins / Penems","number":10,"prompt":"Name the five most veterinary-relevant penicillins and penicillin derivatives, and the most important potentiator for some of these drugs.","answer":"Five key penicillins/derivatives emphasized are penicillin G, amoxicillin, ampicillin, cloxacillin and ticarcillin; clavulanate is the especially important potentiator in companion animals and with selected antipseudomonal formulations. Also recognize intramammary hetacillin and other formulations in the lecture tables.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-046","lecture":"Lecture 3","section":"Penicillins / Penems","number":11,"prompt":"Also provide the unique characteristic(s) of each of the six drugs from the prior question.","answer":"Penicillin G: classic Gram-positive agent with depot/intramammary forms; amoxicillin ± clavulanate: convenient oral small-animal wounds/skin/UTI use; ampicillin: injectable systemic/food-animal contexts; cloxacillin: penicillinase-stable antistaphylococcal mastitis drug; ticarcillin: selected antipseudomonal drug often combined with clavulanate; clavulanate: beta-lactamase inhibitor, not independent broad antibiotic.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-047","lecture":"Lecture 3","section":"Penicillins / Penems","number":12,"prompt":"Provide a clinical application for a penicillin derivative in both companion and food animals.","answer":"Companion animal: amoxicillin/clavulanate for a susceptible infected bite wound; food animal: approved intramammary penicillin derivative for appropriate mastitis or labeled ampicillin in select bovine bacterial infections. Choose by culture, label/withdrawal and patient.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-048","lecture":"Lecture 3","section":"Penicillins / Penems","number":13,"prompt":"Describe why, in general, most penicillins are more effective versus Gm(+) than Gm(-) bacteria.","answer":"Gram-positive bacteria expose a thick peptidoglycan layer without a Gram-negative outer membrane. Gram-negative organisms have an outer membrane/porins and beta-lactamases that may block or destroy drugs before PBP access; exceptions exist.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-049","lecture":"Lecture 3","section":"Penicillins / Penems","number":14,"prompt":"Describe the post-antibiotic effect and how this phenomenon is not relevant to penicillins. Also, why is it irrelevant to treating most Gm(-) infections. You will not be able to answer this question until the aminoglycoside lecture.","answer":"Post-antibiotic effect (PAE) is delayed bacterial regrowth after transient exposure. Most penicillins have limited PAE against many Gram-negative bacteria, so concentrations must remain above MIC; aminoglycosides can have an important PAE and peak-driven activity.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-050","lecture":"Lecture 3","section":"Penicillins / Penems","number":15,"prompt":"Which drugs would you choose versus the following Pseudomonas infection? Why? Refer to the susceptibility/MIC/time-over-MIC table on the reproduced original lecture slide in the appendix.","answer":"From the professor's Pseudomonas table: ticarcillin is favored (MIC 16 µg/mL, breakpoint 128 µg/mL, ~12 hours above MIC). Penicillin (MIC 1000), ampicillin (64 above breakpoint 32) are poor; amoxicillin (32 at breakpoint 32) has only ~4 hours above MIC. Clinical dosing still follows actual susceptibility and approved formulations.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-051","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":1,"prompt":"What is the mechanism of action for each?","answer":"Cephalosporins, carbapenems and monobactams contain beta-lactam rings and inhibit PBPs/peptidoglycan cross-linking. Bacitracin blocks recycling of the lipid carrier that transports wall precursors; glycopeptides bind wall precursors (D-Ala-D-Ala).","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-052","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":2,"prompt":"Bacteriostatic or bactericidal?","answer":"These cell-wall agents are generally bactericidal against susceptible actively growing bacteria. Bacitracin and glycopeptide effects depend on organism and exposure; don't assume every formulation is appropriate systemically.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-053","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":3,"prompt":"What is the major resistance mechanism?","answer":"For beta-lactams: beta-lactamase or cephalosporinase, altered PBPs and limited entry. Carbapenemases and other specialized enzymes matter for reserve agents; bacitracin resistance may involve target/protection/transport changes.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-054","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":4,"prompt":"Any potentiators?","answer":"Imipenem is given with cilastatin, which inhibits renal dehydropeptidase I and protects it from breakdown (a PK potentiator, not beta-lactamase inhibition). The lecture also notes clavulanate with cefpodoxime, but combinations require actual approved formulations and susceptibility support.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-055","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":5,"prompt":"What are the important pharmacokinetic properties of cephalosporins?","answer":"Cephalosporins are mainly time-dependent with renal clearance for many molecules, and dosing interval matters; specific drugs differ in protein binding and tissue distribution. Ceftiofur and cefovecin have special long-lasting formulations.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Describe the pharmacokinetics.","promptEditedForRecall":true},{"id":"carlson186-056","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":6,"prompt":"Any sustained release formulations? Describe flip-flop kinetics of cefovecin.","answer":"Yes: cefovecin and certain ceftiofur formulations. Cefovecin's slow release from its depot/strong protein-associated reservoir can make apparent terminal elimination governed by redistribution/release kinetics ('flip-flop'), rather than intrinsic renal elimination alone; clinically it persists for many days.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-057","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":7,"prompt":"How does antimicrobial coverage change across the five cephalosporin generations, and what exceptions matter?","answer":"General lecture pattern: first-generation favors Gram-positive bacteria; second-generation expands selected Gram-negative coverage; third-generation has stronger Gram-negative coverage for many agents but drug-specific variation; fourth-generation often broad Gram-positive/negative and greater beta-lactamase stability; fifth-generation includes drugs active against some resistant Gram-positive organisms such as MRSA. Do not infer a complete spectrum from generation alone.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Know the spectra of all five generations of cephalosporins.","promptEditedForRecall":true},{"id":"carlson186-058","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":8,"prompt":"Which cephalosporin appears to be the most useful clinically in the absence of resistance?","answer":"The lecture answer slide names cephalexin: common, practical, useful for susceptible Gram-positive skin/soft-tissue infection in small animals; culture and patient needs still determine selection.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-059","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":9,"prompt":"Give two reasons cefpodoxime may be selected instead of cephalexin, and explain the stewardship trade-off.","answer":"Cefpodoxime may be given less frequently (often once daily) and can cover some cephalexin-resistant isolates due to differing spectrum/stability. It is not categorically 'stronger', and the instructor classifies it differently from some modern references.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Give two reasons why cefpodoxime might be preferred over cephalexin. Hints: dose frequency and bacterial resistance.","promptEditedForRecall":true},{"id":"carlson186-060","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":10,"prompt":"Compare the three major ceftiofur formulations in terms of preparation, administration, duration, production convenience, and milk/withdrawal considerations.","answer":"Ceftiofur sodium (Naxcel): aqueous, needs reconstitution, daily, injectable and can be IV in horses where labeled; RTU suspension (Excenel): ready to use, daily SQ/IM where labeled; crystalline free acid (Excede): long-acting, fewer injections, cattle injection-site restrictions such as ear/neck depending on product, and formulation-specific withdrawal. Milk withholding and legal routes vary; verify the exact animal class and product label.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Describe the three formulations of ceftiofur and advantages of each. Hints: some producers like the single-dosing, some producers don’t like to give the injections behind the ear, most producers don’t like to reconstitute drugs, sometimes it may be necessary to give ceftiofur IV. Also, I think all dairy farmers don’t like to throw milk away.","promptEditedForRecall":true},{"id":"carlson186-061","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":11,"prompt":"Should you give cefovecin to a goat that is not ill?.","answer":"No. Cefovecin is not approved for goats, which are food-producing animals, and giving a long-acting antibiotic to a healthy goat 'just in case' is poor stewardship. Extra-label cephalosporin use in food animals is tightly restricted.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-062","lecture":"Lecture 3","section":"Cephalosporins, Carbapenems, Monobactams &","number":12,"prompt":"What are the spectra for carbapenems, monobactams, and bacitracin? [See the spectrum quadrant on the original slide in the appendix.]","answer":"Carbapenems cover a broad range of aerobic/anaerobic Gram-positive and Gram-negative bacteria (with drug-specific exceptions); monobactams such as aztreonam principally affect aerobic Gram-negative organisms; bacitracin primarily targets Gram-positive bacteria and is mostly topical or specialized veterinary use. Verify activity by organism and susceptibility.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-063","lecture":"Lecture 4","section":"Tetracyclines","number":1,"prompt":"Which five tetracycline antibiotics and which related newer antimicrobial should you recognize?","answer":"Recognize oxytetracycline, chlortetracycline, tetracycline, minocycline and doxycycline; tigecycline is the newer related glycylcycline highlighted.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"For tetracyclines, be able to recognize the five relevant ones and the new related drug.","promptEditedForRecall":true},{"id":"carlson186-064","lecture":"Lecture 4","section":"Tetracyclines","number":2,"prompt":"What is the MOA and spectrum of tetracyclines?","answer":"Tetracyclines reversibly bind 30S and prevent productive aminoacyl-tRNA access, usually bacteriostatic. They cover many Gram-positive/negative and atypical/intracellular organisms, including rickettsiae, Chlamydia and some spirochetes; resistance varies greatly.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-065","lecture":"Lecture 4","section":"Tetracyclines","number":3,"prompt":"What is the main mechanism for tetracycline resistance, but which drug is least affected?","answer":"Efflux pumps that expel the drug and ribosomal protection are common. Tigecycline resists several classic efflux/protection mechanisms; doxycycline is less affected by some mechanisms but not universally exempt.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-066","lecture":"Lecture 4","section":"Tetracyclines","number":4,"prompt":"How do bacterial mutations or acquired resistance mechanisms affect tetracycline efficacy?","answer":"Mutations/resistance can accumulate under inadequate drug exposure; tetracycline resistance is commonly carried by acquired tet determinants and can be co-selected. A 'mutant' does not mean tetracyclines kill by causing mutations.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Describe the relationship between tetracyclines and “mutant” bacteria.","promptEditedForRecall":true},{"id":"carlson186-067","lecture":"Lecture 4","section":"Tetracyclines","number":5,"prompt":"What two clinically useful non-antimicrobial effects can tetracyclines have?","answer":"Beyond antibacterial action, tetracyclines can inhibit matrix metalloproteinases (anti-collagenase/anti-inflammatory effect), and some show neuroprotective/immune-modulating effects as discussed in the lecture. These are context- and drug-specific.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Describe two therapeutic effects of tetracyclines that are not related to antimicrobial activity.","promptEditedForRecall":true},{"id":"carlson186-068","lecture":"Lecture 4","section":"Tetracyclines","number":6,"prompt":"How do divalent or trivalent cations affect tetracycline absorption and administration?","answer":"Divalent/trivalent cations (Ca²⁺, Mg²⁺, Fe³⁺, Al³⁺) chelate tetracyclines in the GI tract, decreasing oral absorption; separate dosing from mineral supplements/antacids and consider food/product-specific guidance.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What is the relationship between divalent cations and tetracyclines.","promptEditedForRecall":true},{"id":"carlson186-069","lecture":"Lecture 4","section":"Tetracyclines","number":7,"prompt":"What adverse effects should you monitor for during tetracycline treatment?","answer":"GI upset and dysbiosis, esophageal injury with dry-pill doxycycline in cats, teeth/bone developmental effects for some drugs, photosensitivity and hepatic or renal problems in susceptible patients. Oxytetracycline may cause local tissue irritation; always consider species.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Be able to recognize side effects of tetracyclines.","promptEditedForRecall":true},{"id":"carlson186-070","lecture":"Lecture 4","section":"Tetracyclines","number":8,"prompt":"Why would doxycycline be a poor choice versus a urinary tract infection?","answer":"Doxycycline's fraction excreted unchanged in urine is relatively low compared with some other antibiotics, so it is often a poor choice for uncomplicated lower UTI where high active urinary concentrations are needed. It can still be useful for specifically susceptible pathogens/indications.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-071","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":1,"prompt":"What is the mechanism of action for aminoglycosides?","answer":"Aminoglycosides (gentamicin, amikacin, neomycin) bind the 30S ribosome and cause misreading of mRNA, abnormal proteins and irreversible loss of bacterial function; generally bactericidal against susceptible aerobic organisms.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-072","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":2,"prompt":"Why are aminoglycosides generally bactericidal whereas tetracyclines are usually bacteriostatic?","answer":"Tetracyclines bind reversibly and stop tRNA addition (usually static); aminoglycosides create persistent ribosomal errors and lethal membrane/protein damage, producing bactericidal effects. Their uptake requires bacterial energy/oxygen.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"After next lecture, you should be able to describe why aminoglycosides kill bacteria but tetracyclines do not.","promptEditedForRecall":true},{"id":"carlson186-073","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":3,"prompt":"Compare common clinical uses and routes of gentamicin and amikacin.","answer":"Gentamicin: topical ophthalmic/otic/skin, equine intrauterine for metritis and selected injectable equine Gram-negative sepsis. Amikacin: injectable or regional perfusion for culture-confirmed resistant infections, including joint/limb infection; not a routine broad empiric choice.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Clinical applications summary: gentamicin topical, amikacin injectable.","promptEditedForRecall":true},{"id":"carlson186-074","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":4,"prompt":"Describe the major toxicities for aminoglycosides? How can two of these be avoided by pharmacokinetic (dosing) manipulations? Aminoglycosides versus aminocyclitols in terms of toxicity? Which drugs are worst and which ones are least likely to cause toxicity?","answer":"Nephrotoxicity (proximal tubules), cochlear and vestibular ototoxicity (megalin-mediated uptake and mitochondrial effects), and occasional neuromuscular blockade. High-peak/extended-interval dosing with appropriate monitoring can reduce sustained tubular/ear exposure for some drugs; kanamycin/amikacin/neomycin are notable cochlear risks, streptomycin/gentamicin/tobramycin vestibular risks. Aminocyclitols generally have less ototoxicity, but not zero adverse effects.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-075","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":5,"prompt":"What is a major bacterial mechanism of aminoglycoside resistance?","answer":"Aminoglycoside-modifying enzymes (acetylation, phosphorylation, adenylation) commonly inactivate agents; altered ribosomal binding, efflux and impaired uptake also occur. Amikacin can retain activity against some resistant Gram-negative isolates.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Generally describe the primary mechanism for aminoglycoside resistance.","promptEditedForRecall":true},{"id":"carlson186-076","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":6,"prompt":"Which bacterial groups are intrinsically poorly susceptible to aminoglycosides, and why?","answer":"Obligate anaerobes are intrinsically insensitive because aminoglycoside uptake into bacteria is oxygen/energy dependent. Low oxygen, acidic pus and necrotic sites may similarly impair entry.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What type of bacteria are universally insensitive to aminoglycosides.","promptEditedForRecall":true},{"id":"carlson186-077","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":7,"prompt":"Explain the conundrum with concurrent use of aminoglycosides and beta-lactams.","answer":"They may act synergistically: beta-lactams compromise the cell wall, improving aminoglycoside access. But solutions can chemically inactivate each other if mixed in a syringe/IV line; administer separately and flush appropriately.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-078","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":8,"prompt":"Since these drugs are polar, how do you achieve therapeutic levels in the blood?","answer":"Their polarity prevents reliable systemic oral absorption; inject IV/IM/SQ when systemic blood levels are needed. Topical or oral use is useful for local sites without expecting meaningful systemic absorption.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-079","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":9,"prompt":"What is the regulatory issue regarding food animals and aminoglycosides?","answer":"Systemic extra-label aminoglycoside administration in food-producing animals faces major restrictions and very prolonged residues; many uses are prohibited or impractical. Check species/product regulation and withdrawal guidance.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-080","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":10,"prompt":"What is the issue with aminoglycosides and ruptured tympanic membranes?","answer":"If the tympanic membrane is ruptured, otic aminoglycosides can reach the middle/inner ear and cause hearing or vestibular injury. Confirm tympanic membrane integrity or choose a safer otic agent.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-081","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":11,"prompt":"Why are aminoglycosides poor choices for long-term at-home therapy if the owners are unable to administer injections?","answer":"Oral pills cannot achieve useful systemic concentrations, so owners unable to give injections cannot reliably continue systemic aminoglycoside treatment at home; alternatives and clinic administration may be needed.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-082","lecture":"Lecture 4","section":"Aminoglycosides and Aminocyclitols","number":12,"prompt":"Why can you use these drugs versus cystitis but not versus nephritis?","answer":"Active unmetabolized drug is filtered into urine, yielding useful bladder concentrations for susceptible cystitis organisms. For nephritis/renal parenchymal infection, renal tubular accumulation and toxicity, and less predictable tissue exposure, make them much less attractive; distinguish urine concentration from safe kidney tissue treatment.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-083","lecture":"Lecture 4","section":"Macrolides","number":1,"prompt":"Which three human-use macrolides are also used in veterinary medicine?","answer":"Erythromycin, clarithromycin and azithromycin are the three human-use macrolides discussed that also have selected veterinary uses.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Name the human macrolides (n=3) that can be used in veterinary medicine.","promptEditedForRecall":true},{"id":"carlson186-084","lecture":"Lecture 4","section":"Macrolides","number":2,"prompt":"Which five veterinary-specific macrolides should you recognize?","answer":"Tulathromycin, tilmicosin, tylosin, gamithromycin and tildipirosin are the five veterinary-specific examples emphasized.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"For macrolides, be able to recognize the five veterinary-specific ones.","promptEditedForRecall":true},{"id":"carlson186-085","lecture":"Lecture 4","section":"Macrolides","number":3,"prompt":"What is the MOA and spectrum of macrolides? Static or cidal?","answer":"Macrolides bind 50S and inhibit protein elongation/translocation, generally bacteriostatic; spectrum favors many Gram-positive organisms, selected anaerobes, respiratory pathogens and atypicals including Mycoplasma (species-specific resistance matters), with more limited routine Gram-negative aerobic coverage.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-086","lecture":"Lecture 4","section":"Macrolides","number":4,"prompt":"Which bacteria are typically resistant to macrolides? What about Mycoplasma?","answer":"Most Enterobacterales/other Gram-negative aerobes have poor intrinsic macrolide susceptibility; exceptions and compound-specific activity exist. Mycoplasma lacks a cell wall and may be susceptible to appropriate macrolides, making them useful respiratory agents.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-087","lecture":"Lecture 4","section":"Macrolides","number":5,"prompt":"Describe the primary mechanism for macrolide resistance and how this relates to other antibiotics.","answer":"Ribosomal methylation at the 50S binding site (erm-family mechanisms) lowers drug binding; this can confer MLSB cross-resistance to macrolides, lincosamides and streptogramin B. Efflux also occurs.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-088","lecture":"Lecture 4","section":"Macrolides","number":6,"prompt":"Describe four side effects of erythromycin.","answer":"Erythromycin can cause nausea/vomiting/diarrhea via motilin signaling, injection-site irritation, hepatobiliary toxicity in susceptible contexts, and dysbiosis/severe enterocolitis particularly in hindgut fermenters; drug interactions/QT effects may be important.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-089","lecture":"Lecture 4","section":"Macrolides","number":7,"prompt":"What are the side effect issues with tilmicosin?","answer":"Injectable tilmicosin is cardiotoxic; accidental human self-injection can be fatal, and intravenous administration in animals can cause dangerous arrhythmias. Strict handling/route safeguards and label restrictions are essential.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-090","lecture":"Lecture 4","section":"Macrolides","number":8,"prompt":"Describe the favorable pharmacokinetics of tulathromycin and the two new drugs?","answer":"Tulathromycin, gamithromycin and tildipirosin achieve sustained high pulmonary and intracellular/macrophage concentrations, enabling long dosing intervals and useful BRD therapy/metaphylaxis where labeled. Tissue exposure may exceed plasma exposure; species, formulation and food-animal label remain decisive.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-091","lecture":"Lecture 4","section":"Phenicols","number":1,"prompt":"Give three reasons florfenicol may be preferred over chloramphenicol in appropriate veterinary cases.","answer":"Florfenicol is not associated with the same idiosyncratic fatal human aplastic anemia risk as chloramphenicol; it lacks a key chloramphenicol acetylation site so evades some enzymatic resistance; and it is less prone to certain chloramphenicol-specific marrow toxicities. It also has approved veterinary food-animal formulations where labeled, unlike chloramphenicol.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Name three specific reasons why florfenicol is superior to chloramphenicol (hint: toxicity and resistance)?","promptEditedForRecall":true},{"id":"carlson186-092","lecture":"Lecture 4","section":"Phenicols","number":2,"prompt":"Describe the relationship between phenicols, neurologic disease, and B-lactams.","answer":"Florfenicol penetrates CSF relatively well and may be useful for susceptible meningitis; chloramphenicol also distributes well to protected sites. Beta-lactams may have poorer CSF penetration without meningeal inflammation, but this is drug-dependent—select using susceptibility and disease.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-093","lecture":"Lecture 4","section":"Phenicols","number":3,"prompt":"Why is chloramphenicol banned in food animals?","answer":"Chloramphenicol is banned in food-producing animals because of potentially fatal idiosyncratic aplastic anemia in exposed humans and absence of an acceptable safe residue threshold; handler gloves and exposure reduction matter even in companion animals.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-094","lecture":"Lecture 4","section":"Phenicols","number":4,"prompt":"What are Herxheimer’s reactions?","answer":"Jarisch–Herxheimer-type reactions are acute inflammatory reactions after rapid microbial killing releases microbial components such as LPS/endotoxin, causing fever, hypotension and systemic deterioration. Monitor patients with high bacterial burden; the lecturer links this possibility to bactericidal florfenicol.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-095","lecture":"Lecture 4","section":"Phenicols","number":5,"prompt":"What are the two major clinical indications for florfenicol?","answer":"Major lecturer applications for florfenicol are bovine respiratory disease and swine respiratory disease. Formulations/routes differ; approved-label food residue rules must be obeyed.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-096","lecture":"Lecture 4","section":"Lincosamides","number":1,"prompt":"Clindamycin has a special “affinity” for which type of Gm+ bacteria?","answer":"Clindamycin has particularly useful activity against susceptible Gram-positive anaerobes and many other anaerobic bacteria; the lecturer stresses its affinity for anaerobic oral/dental and bone-associated infection rather than aerobic Gram-negative pathogens.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-097","lecture":"Lecture 4","section":"Lincosamides","number":2,"prompt":"What is the major side effect of clindamycin and how is it treated?","answer":"Antibiotic-associated dysbiosis/pseudomembranous colitis (often C. difficile overgrowth) can cause severe diarrhea; stop the offending antibiotic, give supportive care and use species-appropriate targeted management. Particularly avoid lincosamides in horses/rabbits or other sensitive hindgut fermenters.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-098","lecture":"Lecture 4","section":"Lincosamides","number":3,"prompt":"Why is pirlimycin to be used only in uncomplicated mastitis?","answer":"Pirlimycin is used intramammarily against susceptible uncomplicated Gram-positive mastitis. Severe/deep/systemic infection needs systemic assessment and often additional therapy; local drug exposure alone may not treat disseminated disease.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-099","lecture":"Lecture 4","section":"Lincosamides","number":4,"prompt":"What are the main clinical indications for clindamycin and which species are at high risk of adverse effects?","answer":"Clindamycin is used for susceptible dental/periodontal anaerobic infections, osteomyelitis, anal sac infections and selected soft-tissue infections; it also has antiprotozoal activity against Toxoplasma. It achieves useful bone concentrations but does not reliably cover Gram-negative aerobes.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Know the clinical indications for clindamycin.","promptEditedForRecall":true},{"id":"carlson186-100","lecture":"Lecture 4","section":"Streptogramins and Tiamulin","number":1,"prompt":"Explain why bacteria can’t live without protein synthesis yet most of the 50S inhibitors are only bacteriostatic. Which 50S inhibitors are cidal?","answer":"Protein synthesis inhibition stops growth without necessarily rapidly killing cells because existing proteins persist. The lecture identifies florfenicol, streptogramins and linezolid as 50S agents with bactericidal behavior in its teaching framework; actual static/cidal designation depends on organism and exposure, and linezolid is not universally bactericidal.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-101","lecture":"Lecture 4","section":"Streptogramins and Tiamulin","number":2,"prompt":"What common bacterial resistance mechanisms can affect multiple 50S ribosome inhibitors?","answer":"Methylation/alteration of the 50S ribosomal binding site is a recurring resistance mechanism and can cause cross-resistance among macrolides, lincosamides, streptogramins and other 50S agents.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What is a common resistance theme in the 50S inhibitors.","promptEditedForRecall":true},{"id":"carlson186-102","lecture":"Lecture 4","section":"Streptogramins and Tiamulin","number":3,"prompt":"Why is virginiamycin banned for food animal use in Europe?","answer":"Europe restricted virginiamycin in food animals because of concern about selection of resistant enterococci and transfer/cross-resistance relevant to human streptogramin therapy, especially against vancomycin-resistant Enterococcus.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-103","lecture":"Lecture 4","section":"Streptogramins and Tiamulin","number":4,"prompt":"Describe the pharmacokinetic properties of streptogramins that (a) create a potential food safety hazard and (b) help to eliminate a “hiding place” for a superpathogen.","answer":"Water solubility means injectable systemic therapy may be needed for human streptogramin combinations; poultry feed exposure raises concern about gut contents contaminating carcasses/residues. Their activity against vancomycin-resistant Enterococcus addresses an otherwise protected clinical 'hiding place' for resistant pathogens.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-104","lecture":"Lecture 4","section":"Streptogramins and Tiamulin","number":5,"prompt":"Tiamulin seems to be primarily relegated to which species?","answer":"Tiamulin is used primarily in swine (also some poultry applications), particularly respiratory/enteric infections; dangerous interactions with ionophore feed additives can cause fatal myopathy.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-105","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":1,"prompt":"What is the MOA for FQs and how do they affect overall bacterial cell morphology?","answer":"Fluoroquinolones inhibit bacterial DNA gyrase/topoisomerase II and topoisomerase IV, preventing controlled DNA coiling/segregation and producing lethal DNA damage and abnormal chromosome packaging. They are generally bactericidal.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-106","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":2,"prompt":"What are the mechanisms and bacteriostatic/bactericidal effects of the three other antimicrobial classes in this lecture subsection?","answer":"Novobiocin inhibits the ATP-binding function of bacterial DNA gyrase (usually static); rifampin inhibits bacterial RNA polymerase (usually cidal against susceptible actively growing bacteria); polymyxins disrupt Gram-negative outer membranes and can bind LPS (bactericidal). Also recognize nitroimidazoles such as metronidazole as anaerobe-activated DNA-damaging drugs where included in this section.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Name the MOAs for the other 3 classes of antibiotics in this subsection and be able to classify each based on bacterial killing versus stasis.","promptEditedForRecall":true},{"id":"carlson186-107","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":3,"prompt":"What “subgroup” of bacteria are unaffected by any of the 5 veterinary FQs?","answer":"Anaerobic bacteria are not reliably affected by the routine veterinary fluoroquinolones; drug target/spectrum and permeability differ across organisms.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-108","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":4,"prompt":"Why are fluoroquinolones sometimes described as 'designer drugs'?","answer":"Chemical substitutions on the quinolone scaffold alter uptake, target affinity, spectrum and resistance behavior; this makes FQs a useful example of designing compounds for different pathogens.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Why could FQs be considered “designer drugs”.","promptEditedForRecall":true},{"id":"carlson186-109","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":5,"prompt":"Describe 3 side effects of FQs in dogs, 1 in cats, and 1 in horses?","answer":"In dogs: developmental articular cartilage toxicity, neurologic stimulation/seizures, and GI effects/other interactions; in cats: dose-related retinal degeneration/blindness particularly with enrofloxacin; in horses: GI dysbiosis/colitis and articular cartilage risks in immature animals (drug-specific).","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-110","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":6,"prompt":"Describe the MIC-MPC relationship for FQs.","answer":"MIC is the inhibitory concentration of the susceptible population; mutant prevention concentration (MPC) is an experimental level intended to inhibit first-step resistant mutants. The professor's approximate rule is MPC ≈ 5×MIC for Gram-positive, 10×MIC for Gram-negative organisms; clinically it is not a universal validated target.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-111","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":7,"prompt":"What are the precautions/legal limitations of FQs in food animals?","answer":"US food-animal fluoroquinolones are limited to specifically approved species, indications and label routes; extra-label use in food-producing animals is prohibited. Check current product labeling, withholding and veterinary oversight.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-112","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":8,"prompt":"Name 2 drug interactions of FQs.","answer":"Oral absorption may be reduced by divalent/trivalent metal ions in antacids, dairy/mineral supplements, sucralfate; coadministration with certain NSAIDs or other CNS-active drugs may increase seizure risk in susceptible patients. Interactions vary by agent.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-113","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":9,"prompt":"Describe the post-antibiotic effect.","answer":"PAE is continuing bacterial growth suppression after drug concentrations fall below MIC. FQs may have substantial PAE, supporting exposure-based interval strategies but not permission for underdosing.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-114","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":10,"prompt":"Describe the major basis for FQ resistance.","answer":"Point mutations altering gyrase/topoisomerase targets are major resistance mechanisms; efflux and reduced permeability also contribute. Repeated inadequate exposure selects resistant subpopulations.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-115","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":11,"prompt":"Describe bacterial resistance and MPCs in regards to FQ therapy.","answer":"Ideally dose regimens meet drug/organism-specific AUC/MIC and Cmax/MIC goals and reduce time in a mutant-selection window. A transient peak above an assumed MPC is not a guarantee resistance cannot occur; follow validated PK/PD guidance and stewardship.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-116","lecture":"Lecture 5","section":"Fluoroquinolones & Other Agents — Part 1","number":14,"prompt":"Name an indication for FQs, and one for rifampin.","answer":"Fluoroquinolone example: culture-confirmed susceptible Gram-negative UTI or selected serious infection; rifampin: selected equine Rhodococcus equi pneumonia in combination with a macrolide, because single-agent resistance develops rapidly.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-117","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":1,"prompt":"Explain the difference between synergism and potentiation in regards to antibiotic combinations especially sulfonamides and benzylpyrimidines.","answer":"Synergism means the combination effect exceeds the expected additive antibacterial action. Potentiation often means one agent enables/enhances the other (e.g., enzyme inhibitor preserving active drug); sulfonamide + trimethoprim achieves sequential folate blockade, often bactericidal together although each is generally static alone.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-118","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":2,"prompt":"What are the mechanisms of action for sulfonamides and benzylpyrimidines?","answer":"Sulfonamides compete with PABA for bacterial dihydropteroate synthase (DHPS), impairing folate synthesis; trimethoprim/ormetoprim (benzylpyrimidines) inhibit downstream dihydrofolate reductase (DHFR), preventing reduced folate production and nucleotide synthesis.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-119","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":3,"prompt":"Explain why sulfonamides and benzylpyrimidines do not have a significant effect on the analogous pathway in most eukaryotes.","answer":"Mammals obtain much folate from diet and lack bacterial DHPS; bacterial DHFR is more selectively inhibited than mammalian enzyme at therapeutic exposure. Mammalian folate pathways exist, so high exposure can still cause toxicity.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-120","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":4,"prompt":"Explain resistance versus susceptibility for sulfonamide + benzylpyrimidine combinations, including the spectrum chart.","answer":"Use the specific organism and breakpoint. The slide emphasizes sulfa + BP combinations broaden efficacy and may be bactericidal; if an isolate is truly sulfonamide resistant due to target/bypass mechanisms, the combination may fail. Susceptibility cannot be deduced solely from one generic resistance label; test the actual combination when possible.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-121","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":5,"prompt":"Describe the exploitable pharmacogenetic situation involving dogs and benzylpyrimidine pharmacokinetics (see original slide for related spectrum chart).","answer":"Dogs may convert/metabolize specific benzylpyrimidines differently, affecting active drug persistence/distribution, and trimethoprim can reach the prostate. The lecturer also emphasizes canine susceptibility to sulfonamide adverse reactions including KCS; use dog-specific PK, dose and monitoring rather than assuming cross-species equivalence. Clinical nuance: The original study-guide slide includes overlay text from a spectrum chart, which is reproduced in the source booklet. Confirm any unusual pharmacogenetic drug-specific interpretation with lecture audio.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-122","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":6,"prompt":"What four major adverse effects can sulfonamides cause?","answer":"Common adverse effects: hypersensitivity/immune-mediated reactions, keratoconjunctivitis sicca in dogs, hematologic cytopenias, crystalluria/renal injury; GI upset, hepatic dysfunction and thyroid changes can also occur depending on drug/duration.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Name four side effects of sulfonamides. Gm(-) Sulfas+BP Sulfas+BP","promptEditedForRecall":true},{"id":"carlson186-123","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":7,"prompt":"What pathogen “group” should NOT be treated with sulfonamides and why?","answer":"Rickettsiae should generally NOT be treated with sulfonamides; the lecture notes folate metabolic effects can paradoxically promote their growth or worsen infection. Doxycycline is preferred for susceptible rickettsial disease.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-124","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":8,"prompt":"What is the basis for resistance to sulfonamides and benzylpyrimidines?","answer":"Altered DHPS/DHFR targets, increased substrate production, drug efflux and bypass/alternative folate uptake cause resistance; plasmid-acquired genes are important.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-125","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":9,"prompt":"Why are sulfonamides and benzylpyrimidines ineffective in abscesses or pus?","answer":"Pus/necrotic foci have poor perfusion and can contain extracellular thymidine/PABA-like substrates that bypass the antimicrobial's folate pathway; drainage and culture matter. This is not an absolute rule for every abscess.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-126","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":10,"prompt":"Name the two sulfonamides used versus enteric infections and why these drugs are used as such.","answer":"Poorly absorbed enteric sulfonamides highlighted are sulfaguanidine and phthalylsulfathiazole (check slide formulation availability); they act mainly in the intestinal lumen because systemic absorption is limited.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-127","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":11,"prompt":"Which bacterial (morphologic) “group” is resistant to these sulfonamides.","answer":"Enterococci and Pseudomonas are important poor-coverage groups for typical sulfonamide combinations (the lecturer highlights resistant Gram-positive cocci/Gram-negative nonfermenters). Always use local susceptibility rather than relying on morphology alone.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-128","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":12,"prompt":"How do ionophores work and what species is very sensitive to these drugs?","answer":"Ionophores such as monensin and lasalocid shuttle Na+, K+ and H+ across susceptible membranes, collapsing ionic gradients and intracellular pH. Horses are extremely sensitive: skeletal/cardiac muscle necrosis can be fatal, especially with feed contamination.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-129","lecture":"Lecture 5","section":"Sulfonamides, Benzylpyrimidines & Ionophores — Part 2","number":13,"prompt":"Name two non-infectious uses for ionophores.","answer":"Noninfectious uses include improving feed conversion/growth through rumen fermentation shifts toward propionate and prevention of ruminal acidosis/bloat (and the lecturer discusses prevention of tryptophan-associated fog fever in specific cattle feeding contexts).","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-130","lecture":"Lectures 6–7","section":"NSAIDs I","number":1,"prompt":"Name some general clinical indications for the use of NSAIDs, e.g. analgesia, pyrexia, etc.","answer":"Treat inflammatory/nociceptive pain, fever/pyrexia, and selected tissue inflammation/osteoarthritis while minimizing cognitive sedation. Disease-directed management remains necessary.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-131","lecture":"Lectures 6–7","section":"NSAIDs I","number":2,"prompt":"What types of pain are mitigated by NSAIDs and which types are not completely influenced by NSAIDs?","answer":"NSAIDs help prostaglandin-mediated acute inflammatory and chronic musculoskeletal pain (including some visceral pain, depending on drug). Pure neuropathic pain, severe central sensitization and non-inflammatory components are not fully controlled by NSAIDs alone.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-132","lecture":"Lectures 6–7","section":"NSAIDs I","number":3,"prompt":"How do NSAIDs alter nocioception?","answer":"Inflammatory PGE2 lowers the activation threshold of peripheral nociceptors; COX inhibition reduces sensitization, so an equal physical stimulus produces less pain. NSAIDs also influence central fever/pain pathways.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-133","lecture":"Lectures 6–7","section":"NSAIDs I","number":4,"prompt":"Name three functions of COX1 in homeostasis.","answer":"COX-1 contributes to gastric mucus/bicarbonate and mucosal perfusion, renal blood-flow homeostasis, and platelet thromboxane synthesis/aggregation. These protective functions explain multiple toxicities.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-134","lecture":"Lectures 6–7","section":"NSAIDs I","number":5,"prompt":"How do COX1 and COX2 differ, in general terms, regarding basal activity?","answer":"COX-1 is often constitutively expressed ('housekeeping'), while COX-2 is often inducible by inflammation; COX-2 also has normal kidney/vascular roles and COX-1 can contribute to inflammation, so it is not an absolute separation.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-135","lecture":"Lectures 6–7","section":"NSAIDs I","number":6,"prompt":"Which is a potentially better NSAID target- COX1 and COX2- and why?","answer":"COX-2-selective agents can preferentially reduce inflammatory prostaglandins while sparing some COX-1 GI/platelet functions. They are not renal-safe or free from GI adverse effects.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-136","lecture":"Lectures 6–7","section":"NSAIDs I","number":7,"prompt":"How do NSAIDs reduce fever and what COX may be involved?","answer":"Suppression of prostaglandin E2 in the hypothalamus lowers an elevated thermoregulatory set point and permits heat dissipation. COX-2 is important in the inflammatory response; lecture mentions tissue/species-specific COX-3 interpretations, which are not a universal mechanism.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-137","lecture":"Lectures 6–7","section":"NSAIDs I","number":8,"prompt":"How do NSAIDs alter two important parts of inflammation?","answer":"NSAIDs diminish inflammatory vasodilation/exudation and reduce prostaglandin-mediated pain sensitization. This decreases clinical swelling and discomfort but doesn't eliminate all leukocyte recruitment/underlying cause.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-138","lecture":"Lectures 6–7","section":"NSAIDs I","number":9,"prompt":"Why does co-inhibition of LOX help to minimize an NSAID side effect?","answer":"Dual COX/LOX inhibition can limit some leukotriene-mediated inflammatory processes and, in the lecture model, mitigate GI toxicity when arachidonic acid is diverted to LOX. However, GI benefit is not guaranteed and class-specific safety still matters.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-139","lecture":"Lectures 6–7","section":"NSAIDs I","number":10,"prompt":"Name four adverse effects of NSAIDs and the basis for each.","answer":"Four: GI ulcer/bleeding (loss of protective PGs), renal injury (loss of prostaglandin support for perfusion in volume depletion), platelet dysfunction/bleeding (TXA2 suppression, especially aspirin), and hepatic injury/idiosyncratic reactions (selected agents such as carprofen). Also consider delayed healing and fetal effects.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-140","lecture":"Lectures 6–7","section":"NSAIDs I","number":11,"prompt":"Name four drug types that should NOT be combined with NSAIDs.","answer":"Avoid stacking with glucocorticoids, other NSAIDs/aspirin, drugs that greatly increase bleeding risk (e.g., anticoagulants), and nephrotoxic or perfusion-impairing combinations (e.g., some diuretics/ACE inhibitors in vulnerable patients). Assess each clinical setting rather than imposing blanket universal prohibitions.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-141","lecture":"Lectures 6–7","section":"NSAIDs I","number":12,"prompt":"Why are NSAIDs ineffective versus RA?","answer":"NSAIDs reduce pain/inflammation in rheumatoid arthritis but do not correct immune-mediated joint destruction; disease-modifying immunosuppression is needed for true autoimmune arthritis. They may also obscure progression if used alone.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-142","lecture":"Lectures 6–7","section":"NSAIDs II","number":1,"prompt":"Which NSAIDs are sometimes used in cats, and how do their safety and labeling restrictions differ?","answer":"The lecturer highlights limited feline options, notably robenacoxib, carefully restricted single-dose meloxicam and low-dose aspirin in selected historic uses. These are not equally 'safe': product-specific feline approvals/duration and serious renal risk matter; long-term unsupervised NSAIDs are unsafe.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Name the three NSAIDs that are safe(st) in cats.","promptEditedForRecall":true},{"id":"carlson186-143","lecture":"Lectures 6–7","section":"NSAIDs II","number":2,"prompt":"Name the COX2-selective NSAIDs and why do these drugs spare the GI tract?","answer":"COX-2-preferential veterinary drugs include carprofen, meloxicam, piroxicam, deracoxib, firocoxib, robenacoxib and etodolac to differing degrees. Greater COX-2 selectivity tends to spare COX-1-related gastric protection, but actual GI/renal safety is dose- and patient-dependent.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-144","lecture":"Lectures 6–7","section":"NSAIDs II","number":3,"prompt":"Name the NSAID that can treat visceral pain.","answer":"Flunixin meglumine is classically associated with equine visceral pain/colic; it relieves signs without necessarily fixing obstruction or strangulation, so repeat examination is critical.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-145","lecture":"Lectures 6–7","section":"NSAIDs II","number":4,"prompt":"Name two NSAIDs that are used or can be used vs. endotoxemia.","answer":"Flunixin is used to reduce effects of endotoxemia (inflammatory prostanoids); the lecture also discusses tepoxaline or ketamine as adjuncts in selected settings. Polymyxin B is an anti-endotoxin agent but is not an NSAID; don't confuse these mechanisms.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-146","lecture":"Lectures 6–7","section":"NSAIDs II","number":5,"prompt":"Why would you prescribe carprofen in dogs and what is the major risk?","answer":"Carprofen is common in canine osteoarthritis/inflammatory pain; the signature concern is rare idiosyncratic hepatotoxicity, in addition to class-wide GI and renal injury. Watch anorexia, vomiting, jaundice and laboratory changes.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-147","lecture":"Lectures 6–7","section":"NSAIDs II","number":6,"prompt":"Name two NSAIDs that are banned in food animals?","answer":"Phenylbutazone is prohibited in food-producing animals in many jurisdictions and diclofenac poses serious food-chain/ecologic hazards; certain NSAIDs have species/product-specific prohibitions. Verify rules rather than assuming all compounds share the same legal classification.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-148","lecture":"Lectures 6–7","section":"NSAIDs II","number":7,"prompt":"Why did some of the coxibs get removed from the marketplace and why is this not a problem in dogs? Name two coxibs used in veterinary medicine.","answer":"Certain human coxibs were withdrawn because chronic COX-2 blockade can shift prostacyclin/thromboxane balance and increase thrombosis/cardiovascular events. The lecture suggests dogs have less human-like atherothrombotic risk; that does not mean zero CV risk. Veterinary examples include deracoxib and firocoxib (also robenacoxib).","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-149","lecture":"Lectures 6–7","section":"NSAIDs II","number":8,"prompt":"Name the NSAID approved in swine.","answer":"The lecture includes swine-approved NSAID dipyrone/metamizole historically, but subsequent slides identify its withdrawal and describe newer approvals for other species. Current swine product approvals must be checked separately; do not assume historical swine use equals current approval. Clinical nuance: Instructor slide includes a historical swine-use question. Approval changes by date and jurisdiction; verify current swine NSAID labels before clinical use.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-150","lecture":"Lectures 6–7","section":"NSAIDs II","number":9,"prompt":"Name two NSAIDs that are preferred in horses.","answer":"Phenylbutazone ('bute') for equine musculoskeletal pain, and flunixin for visceral pain/endotoxemia; firocoxib is another equine option.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-151","lecture":"Lectures 6–7","section":"NSAIDs II","number":10,"prompt":"Why is acetaminophen a weak NSAID or maybe not even an NSAID?","answer":"Acetaminophen acts mainly centrally for analgesia and antipyresis with limited peripheral anti-inflammatory COX inhibition. It is not a typical NSAID; cats are particularly susceptible to life-threatening oxidative hemoglobin injury.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-152","lecture":"Lectures 6–7","section":"NSAIDs II","number":11,"prompt":"Why is the route of administration an advantage for meloxicam & robenacoxib?","answer":"Meloxicam and robenacoxib have formulations that can support different routes (oral/injectable according to species and label), improving administration when the patient cannot take one route. This does not override feline duration restrictions.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-153","lecture":"Lectures 6–7","section":"NSAIDs II","number":12,"prompt":"What is unique about tepoxaline? Why is it gastroprotective?","answer":"Tepoxaline inhibits COX-1, COX-2 and LOX, potentially limiting leukotriene-mediated GI consequences in the lecturer's proposed mechanism. The drug's availability and actual GI safety should be confirmed.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-154","lecture":"Lectures 6–7","section":"NSAIDs II","number":13,"prompt":"What is the unique clinical application of piroxicam? Other drug used with it?","answer":"Piroxicam is used in selected canine transitional-cell/urothelial carcinoma regimens for anti-tumor/prostaglandin effects, often paired with chemotherapy such as mitoxantrone. Monitor GI and renal adverse effects.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-155","lecture":"Lectures 6–7","section":"NSAIDs II","number":14,"prompt":"What appears to be the only safe NSAID for long-term use in cats?","answer":"The professor emphasizes robenacoxib as a relatively practical feline short-course option; this does NOT establish a universally safe indefinite feline NSAID. Duration/approval and renal surveillance must be product-specific. Clinical nuance: Instructor framing of feline “long-term safety” must not be read as approval for indefinite dosing.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-156","lecture":"Lectures 6–7","section":"NSAIDs II","number":15,"prompt":"What is the obstacle to long-term treatment with phenylbutazone in horses?","answer":"Long-term phenylbutazone risks equine GI ulceration, right dorsal colitis, protein loss and renal injury; use lowest effective exposure and follow-up assessment.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-157","lecture":"Lectures 6–7","section":"NSAIDs II","number":16,"prompt":"Describe how ketamine could be an adjunct to treat endotoxicosis.","answer":"Ketamine is an NMDA-receptor antagonist that may attenuate central sensitization/pain and inflammatory responses during endotoxemia; it is an adjunct, not a direct endotoxin-neutralizing NSAID or substitute for resuscitation.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-158","lecture":"Lectures 6–7","section":"NSAIDs II","number":17,"prompt":"Why does aspirin cause such profound bleeding disorders?","answer":"Aspirin irreversibly acetylates platelet COX-1, suppressing TXA2 for the lifespan of circulating platelets; new platelets must be made to restore function. Other reversible NSAIDs do not necessarily cause as prolonged a platelet effect.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-159","lecture":"Lectures 6–7","section":"NSAIDs II","number":18,"prompt":"Why are some NSAIDs contraindicated in pregnant animals?","answer":"Fetal prostaglandins support ductus arteriosus patency and other reproductive processes; NSAID exposure can cause premature ductal constriction, fetal renal changes or interfere with labor, depending on gestation and drug.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-160","lecture":"Lectures 6–7","section":"NSAIDs II","number":19,"prompt":"For DMSO, describe the precaution, its use with another drug group, and a clinical application.","answer":"DMSO can carry contaminants/transdermal compounds, so handle with clean gloves/skin and use appropriate formulations. Its free-radical scavenging/anti-inflammatory effects may permit selected use alongside corticosteroids in lecture examples; specific topical veterinary uses include lick granulomas, but it is not a standard COX inhibitor.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-161","lecture":"Lectures 6–7","section":"NSAIDs II","number":20,"prompt":"Best NSAID group for long-term use in dogs?","answer":"COX-2-selective coxibs are common options for long-term canine osteoarthritis because they reduce pain/inflammation while tending to spare some COX-1 functions. Continue renal/GI monitoring, and consider weight, rehabilitation and non-NSAID OA therapies.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-162","lecture":"Lecture 8","section":"Antihistamines","number":1,"prompt":"What are histamine's normal physiological roles and its important roles in disease?","answer":"Histamine normally supports CNS alertness, gastric acid secretion and local inflammatory vascular regulation; during allergy it contributes to pruritus, vasodilation, vascular leakage and some bronchial effects. These functions explain both therapeutic actions and adverse effects of blockade.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What are the functions of histamine in physiological and pathophysiological conditions? • •","promptEditedForRecall":true},{"id":"carlson186-163","lecture":"Lecture 8","section":"Antihistamines","number":2,"prompt":"Where is histamine synthesized and stored, and what stimulates its release?","answer":"Histamine is produced from histidine via histidine decarboxylase and stored/released from mast cells, basophils, histaminergic neurons and gastric enterochromaffin-like cells. IgE-allergen cross-linking, inflammatory signals, wakefulness pathways and gastrin respectively influence its release; somatostatin suppresses gastric release.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Describe histamine storage and release. •","promptEditedForRecall":true},{"id":"carlson186-164","lecture":"Lecture 8","section":"Antihistamines","number":3,"prompt":"Name the histamine receptor subtypes and compare H1- and H2-mediated effects.","answer":"H1 receptors mediate many allergic vascular/pruritic responses and CNS wakefulness/vestibular signaling; H2 receptors on gastric parietal cells increase cAMP and acid secretion. H3 autoreceptors regulate neuronal histamine release; H4 is involved in immune-cell signaling. Clinically H1 and H2 are the lecture focus.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What are the different types of histamine receptors? Understand the role of H1 receptor and H2 receptor-mediated effects of histamine. •","promptEditedForRecall":true},{"id":"carlson186-165","lecture":"Lecture 8","section":"Antihistamines","number":4,"prompt":"Which physiological antagonists can reduce clinically important histamine-mediated effects?","answer":"Physiological/functional antagonists of histamine include epinephrine (alpha-mediated vascular constriction and beta2 bronchodilation), glucocorticoids (reduce delayed inflammatory response), and selected bronchodilators. In anaphylaxis, epinephrine is first-line; H1 blockers are adjuncts and do not reverse shock.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"List the names of common physiological antagonists used to block the adverse effects of histamine. •","promptEditedForRecall":true},{"id":"carlson186-166","lecture":"Lecture 8","section":"Antihistamines","number":5,"prompt":"What are the major adverse effects of first-generation H1 antihistamines?","answer":"First-generation H1 blockers cross the blood-brain barrier and often cause sedation, anticholinergic dry mouth/urinary retention, paradoxical excitement and GI/coordination changes. Avoid assuming all animals respond alike.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"What are the major side effects of first-generation H1 anti-histamines? • •","promptEditedForRecall":true},{"id":"carlson186-167","lecture":"Lecture 8","section":"Antihistamines","number":6,"prompt":"Name common second-generation H1 antihistamines and their clinical uses.","answer":"Second-generation H1 agents include cetirizine, loratadine and fexofenadine; typically less CNS sedation and may help mild allergic pruritus/urticaria in selected patients. Veterinary response is variable and they are not substitutes for emergency anaphylaxis therapy.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"List the names of second-generation H1 anti-histamines and therapeutic uses. •","promptEditedForRecall":true},{"id":"carlson186-168","lecture":"Lecture 8","section":"Antihistamines","number":7,"prompt":"How does histamine stimulate gastric acid secretion?","answer":"Gastrin from G cells stimulates ECL-cell histamine release; histamine activates H2 on parietal cells (Gs → cAMP) to increase the H+/K+-ATPase and HCl secretion. Somatostatin reduces the pathway; PPIs block the downstream pump.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Describe the role of histamine in gastric acid secretion. •","promptEditedForRecall":true},{"id":"carlson186-169","lecture":"Lecture 8","section":"Antihistamines","number":8,"prompt":"List the names of H2 receptor blockers and their therapeutic uses.","answer":"H2 blockers include famotidine, cimetidine, ranitidine and nizatidine (availability changes). They reduce gastric acid secretion in appropriate ulcer/reflux settings but PPIs may give more sustained acid control for many conditions; cimetidine has notable drug-interaction potential.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-170","lecture":"Lecture 9","section":"Corticosteroids Part I","number":1,"prompt":"How do corticosteroids inhibit PLA2?","answer":"Glucocorticoids bind intracellular receptors and induce lipocortin/annexin-1, which inhibits phospholipase A2, reducing arachidonic acid release. They also suppress inflammatory gene transcription/cytokines; both prostaglandin and leukotriene pathways are affected upstream of NSAIDs.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-171","lecture":"Lecture 9","section":"Corticosteroids Part I","number":2,"prompt":"What is the general vascular MOA for the anti-inflammatory effects of corticosteroids?","answer":"They lower capillary permeability and inflammatory exudation, limit leukocyte migration/mediators, and reduce edema. This relieves symptoms but compromises normal defense and healing.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-172","lecture":"Lecture 9","section":"Corticosteroids Part I","number":3,"prompt":"What clinical conditions can benefit from glucocorticoid therapy, and why?","answer":"Atopic dermatitis/asthma, immune-mediated hemolytic anemia, pemphigus and other immune disease can benefit; confirmed primary hypoadrenocorticism requires physiologic replacement rather than immune suppression. Consider infection and underlying cause first.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Be able to recognize a disease that will benefit from corticosteroid therapy.","promptEditedForRecall":true},{"id":"carlson186-173","lecture":"Lecture 9","section":"Corticosteroids Part I","number":4,"prompt":"What adverse effects can glucocorticoids cause, and what mechanism underlies them?","answer":"PU/PD/PP, panting, hyperglycemia/diabetes, muscle wasting, fragile skin/delayed wound healing, infection susceptibility and iatrogenic hyperadrenocorticism are classic. Long-term treatment suppresses the HPA axis.","reviewStatus":"answered-study-booklet; medical audit pending","originalPrompt":"Be able to recognize a side effect associated with corticosteroid therapy.","promptEditedForRecall":true},{"id":"carlson186-174","lecture":"Lecture 9","section":"Corticosteroids Part I","number":5,"prompt":"What are the two main corticosteroids indicated for use in cats?","answer":"Prednisolone and methylprednisolone are emphasized for cats; prednisolone is active without needing hepatic conversion of prednisone. Long-acting depot methylprednisolone has prolonged irreversible exposure and diabetes risk in predisposed/obese cats.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-175","lecture":"Lecture 9","section":"Corticosteroids Part I","number":6,"prompt":"What is the corticosteroid indicated for use against bovine ketosis?","answer":"Dexamethasone is highlighted for bovine ketosis in the lecture context, through hepatic gluconeogenic and metabolic effects; investigate and treat negative energy balance and check relevant food-animal labeling/withdrawal.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-176","lecture":"Lecture 9","section":"Corticosteroids Part I","number":7,"prompt":"Name the drug used to replace mineralocorticoid activity.","answer":"Fludrocortisone (oral) and desoxycorticosterone pivalate/DOCP (injectable) replace mineralocorticoid function in hypoadrenocorticism; glucocorticoid supplementation may also be necessary because DOCP has negligible glucocorticoid action. Clinical nuance: DOCP provides mineralocorticoid but minimal glucocorticoid activity; the professor’s general statement about both products having decent GC activity should not be used to omit prednisone/prednisolone when indicated.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-177","lecture":"Lecture 9","section":"Corticosteroids Part I","number":8,"prompt":"How are horses and cats similar in regards to corticosteroid therapy?","answer":"Horses and cats are less reliable at converting prednisone to prednisolone, so choose active prednisolone when systemic oral GC therapy is required. Species drug metabolism matters more than treating all corticosteroids as interchangeable.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-178","lecture":"Lecture 9","section":"Corticosteroids Part I","number":9,"prompt":"Why is depo-methylprednisolone a second choice in atopic dogs but a viable first choice in cats?","answer":"Depot methylprednisolone can provide practical long control for an unpillable cat but carries diabetes and prolonged immunosuppression risk. Dogs with atopy generally benefit from titratable, shorter-duration agents to allow tapering or stopping as adverse effects arise.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-179","lecture":"Lecture 9","section":"Corticosteroids Part I","number":10,"prompt":"Which is more likely to require corticosteroid replacement therapy after receiving corticosteroid therapy- an atopic dog or a dog with pemphigus?","answer":"A dog with pemphigus usually receives higher-dose, longer-duration immunosuppression and is more likely to have clinically meaningful HPA suppression/need a taper than an atopic dog treated with an intermittent, shorter course. Patient-to-patient variation exists.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-180","lecture":"Lecture 9","section":"Corticosteroids Part II","number":1,"prompt":"Name three advantages for triamcinolone.","answer":"Triamcinolone offers potent anti-inflammatory effects, minimal mineralocorticoid activity (less salt/water retention), and useful topical/intralesional administration for focal lesions. It can still strongly suppress HPA function; 'minimal mineralocorticoid' does not mean harmless.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-181","lecture":"Lecture 9","section":"Corticosteroids Part II","number":2,"prompt":"Which topical corticosteroid would be a good choice if you were especially concerned about side effects in a patient?","answer":"Mometasone is highlighted because low systemic absorption from nasal/topical use reduces systemic adverse effects while retaining local efficacy. Appropriate site/formulation and local adverse effects still matter.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-182","lecture":"Lecture 9","section":"Corticosteroids Part II","number":3,"prompt":"Name two drugs that should not be used in conjunction with corticosteroids.","answer":"Avoid NSAIDs with glucocorticoids because combined suppression of GI defenses markedly increases ulcer/bleeding risk; avoid potassium-wasting diuretics and/or digitalis interactions because glucocorticoid-related hypokalemia may worsen arrhythmia/digoxin toxicity. The slide explicitly mentions both digitalis and hypokalemia-producing diuretics.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-183","lecture":"Lecture 9","section":"Corticosteroids Part II","number":4,"prompt":"Name the adrenolytic drug and describes how it works.","answer":"Mitotane is the adrenolytic DDT-derived agent; it selectively destroys adrenal zona fasciculata/reticularis, reducing cortisol output, and can induce hypoadrenocorticism requiring replacement. Monitor carefully.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-184","lecture":"Lecture 9","section":"Corticosteroids Part II","number":5,"prompt":"Name the six drugs that reduce corticosteroid secretion and the MOA for each.","answer":"Six anti-secretion drugs emphasized: trilostane inhibits 3β-hydroxysteroid dehydrogenase; ketoconazole inhibits steroidogenic cytochrome P450 enzymes; selegiline inhibits MAO-B and alters dopamine signaling to reduce pituitary ACTH in selected disease; bromocriptine, cabergoline and pergolide are D2 agonists reducing pituitary ACTH/POMC signaling. The lecture also discusses etomidate, an emergency 11β-hydroxylase inhibitor, as an additional agent beyond those six. Clinical nuance: The question asks for six drugs, but lecture also separately mentions etomidate in an emergency context.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-185","lecture":"Lecture 9","section":"Corticosteroids Part II","number":6,"prompt":"What long-term therapy will be need after adrenolytic therapy?","answer":"After true adrenal destruction/adrenolytic therapy, long-term physiologic glucocorticoid replacement may be required if cortisol production is inadequate. Mineralocorticoid replacement depends on zona glomerulosa function and electrolytes; mitotane often spares this layer but can still cause Addisonian crises.","reviewStatus":"answered-study-booklet; medical audit pending"},{"id":"carlson186-186","lecture":"Lecture 9","section":"Corticosteroids Part II","number":7,"prompt":"What side effect is common to trilostane and ketoconazole but not relevant for the other secretion inhibitors?","answer":"Reproductive/sex-steroid suppression is associated with both trilostane and ketoconazole because they inhibit multiple steroidogenic pathways; ketoconazole additionally poses hepatic and interaction hazards. Selegiline/D2 agonists act centrally and do not directly suppress all adrenal sex-steroid enzymes in the same way.","reviewStatus":"answered-study-booklet; medical audit pending"}];
